Q: BCryptSetProperty KDF to SHA256 fails for ECDH_P256 on Windows 25H2 26200.6584 and later A: <p>if look for <code>MSCryptEcDhSetProperty</code> implementation (which called from <code>BCryptSetProperty</code> on ECDH keys, code is look like</p>
<pre><code>#define BCRYPT_KEY_MAGIC        'MSKY'
#define BCRYPT_ALG_MAGIC        'MSAL'
#define BCRYPT_SECRET_MAGIC     'MSEC'

typedef struct BCRYPT_OBJECT_HEADER {
    ULONG cbSize;
    ULONG Magic;
} *PBCRYPT_OBJECT_HEADER;

void WPP_SF_sDsd(TRACEHANDLE LoggerHandle, PVOID, PVOID, NTSTATUS status, PCSTR msg, PCSTR file, ULONG line);

void DebugTraceError(NTSTATUS status, PCSTR msg, PCSTR file, ULONG line)
{
    if (WPP_GLOBAL_Control.Next != &amp;WPP_GLOBAL_Control &amp;&amp; (WPP_GLOBAL_Control.Flags &amp; 1)) 
    { 
        WPP_SF_sDsd(WPP_GLOBAL_Control.LoggerHandle, 0, 0, status, msg, file, line);
    }
}

#define LOG_ERROR(status) DebugTraceError(status, &quot;Status&quot;, __FILE__, __LINE__)

inline BOOLEAN ValidateEccHandle(_In_ PBCRYPT_OBJECT_HEADER hObject)
{
    if (!hObject || hObject-&gt;cbSize &lt; sizeof(BCRYPT_OBJECT_HEADER) + 4)
    {
        LOG_ERROR(STATUS_INVALID_HANDLE);// onecore\ds\security\cryptoapi\ncrypt\msprim\ecc\ecc.c(438):
        return FALSE;
    }

    switch (hObject-&gt;Magic)
    {
    case BCRYPT_KEY_MAGIC:
    case BCRYPT_ALG_MAGIC:
        return TRUE;
    }

    LOG_ERROR(STATUS_INVALID_HANDLE);// onecore\ds\security\cryptoapi\ncrypt\msprim\ecc\ecc.c(446):
    return FALSE;
}

NTSTATUS WINAPI MSCryptEcDhSetProperty(
    _In_ PBCRYPT_OBJECT_HEADER hObject,
    _In_ LPCWSTR pszProperty, 
    _In_reads_bytes_(cbInput) PUCHAR pbInput,
    _In_ ULONG cbInput, 
    _In_ ULONG dwFlags 
)
{
    NTSTATUS status;

    if (dwFlags) 
    {
        LOG_ERROR(STATUS_INVALID_PARAMETER);// onecore\ds\security\cryptoapi\ncrypt\msprim\ecc\ecc.c(4017):
        return STATUS_INVALID_PARAMETER;
    }

    if (!ValidateEccHandle(hObject))
    {
        LOG_ERROR(STATUS_INVALID_PARAMETER);// onecore\ds\security\cryptoapi\ncrypt\msprim\ecc\ecc.c(4024):
        return STATUS_INVALID_PARAMETER;
    }

    switch (hObject-&gt;Magic)
    {
    case BCRYPT_KEY_MAGIC:
        if (0 &gt; (status = MSCryptEccSetKeyProperty(hObject, pszProperty, pbInput, cbInput, 0))) 
        {
            LOG_ERROR(status);// onecore\ds\security\cryptoapi\ncrypt\msprim\ecc\ecc.c(4041):
        }
        return status;

    case BCRYPT_ALG_MAGIC:
        if (0 &gt; (status = MSCryptEccSetAlgProperty(hObject, pszProperty, pbInput, cbInput, 0))) 
        {
            LOG_ERROR(status);// onecore\ds\security\cryptoapi\ncrypt\msprim\ecc\ecc.c(4054):
        }
        return status;

    case BCRYPT_SECRET_MAGIC:
        if (0 &gt; (status = MSCryptSetPropertySecret(hObject, pszProperty, pbInput, cbInput, 0))) 
        {
            LOG_ERROR(status);// onecore\ds\security\cryptoapi\ncrypt\msprim\ecc\ecc.c(4067):
        }
        return status;
    }

    LOG_ERROR(STATUS_NOT_SUPPORTED);// onecore\ds\security\cryptoapi\ncrypt\msprim\ecc\ecc.c(4074):
    return STATUS_NOT_SUPPORTED;
}
</code></pre>
<p>code of <code>MSCryptEcDhSetProperty</code> is correct. this function handle 3 types of objects - ALG ( 'MSAL' ), KEY ( 'MSKY' ) and SECRET ('MSEC'). this function was in onecore\ds\security\cryptoapi\ncrypt\msprim\ecc\ecc.c file at lines 4000-4100 approximately. but at some moment, in begin of this function was inserted some validation function <code>ValidateEccHandle</code> - it was in the same file (ecc.c) but at lines 430-450 approximately. and this function containing bug - it forget about <code>BCRYPT_SECRET_MAGIC</code> case. as result when we try set any property on <code>BCRYPT_SECRET_HANDLE</code> we got error <code>STATUS_INVALID_HANDLE</code></p>

